   137  otError CoapBase::SendMessage(Message &               aMessage,
   138                                const Ip6::MessageInfo &aMessageInfo,
   139                                otCoapResponseHandler   aHandler,
   140                                void *                  aContext)
   141  {
   142      otError      error;
   143      CoapMetadata coapMetadata;
   144      Message *    storedCopy = NULL;
   145      uint16_t     copyLength = 0;
   146
   147      if ((aMessage.GetType() == OT_COAP_TYPE_ACKNOWLEDGMENT || aMessage.GetType() == OT_COAP_TYPE_RESET) &&
   148          aMessage.GetCode() != OT_COAP_CODE_EMPTY)
   149      {
   150          mResponsesQueue.EnqueueResponse(aMessage, aMessageInfo);
   151      }
   152
   153      // Set Message Id if it was not already set.
   154      if (aMessage.GetMessageId() == 0 &&
   155          (aMessage.GetType() == OT_COAP_TYPE_CONFIRMABLE || aMessage.GetType() == OT_COAP_TYPE_NON_CONFIRMABLE))
   156      {
   157          aMessage.SetMessageId(mMessageId++);
   158      }
   159
   160      aMessage.Finish();
   161
   162      if (aMessage.IsConfirmable())
   163      {
   164          // Create a copy of entire message and enqueue it.
   165          copyLength = aMessage.GetLength();
   166      }
   167      else if (aMessage.IsNonConfirmable() && (aHandler != NULL))
   168      {
   169          // As we do not retransmit non confirmable messages, create a copy of header only, for token information.
   170          copyLength = aMessage.GetOptionStart();
   171      }
   172
   173      if (copyLength > 0)
   174      {
   175          coapMetadata = CoapMetadata(aMessage.IsConfirmable(), aMessageInfo, aHandler, aContext);
   176          VerifyOrExit((storedCopy = CopyAndEnqueueMessage(aMessage, copyLength, coapMetadata)) != NULL,
   177                       error = OT_ERROR_NO_BUFS);
   178      }
   179
   180      SuccessOrExit(error = Send(aMessage, aMessageInfo));
